                print("=== LOGIN JOB ===")
                for k, v in job.items():
                    if k == "blob":
                        print(f"  blob_len: {len(v)} chars")
                        print(f"  blob_first40: {v[:40]}")
                    else:
                        print(f"  {k}: {v}")
        elif "method" in j:
            method = j["method"]
            params = j.get("params", {})
            print(f"\n=== NOTIFY: {method} ===")
            if isinstance(params, dict):
                for k, v in params.items():
                    if k == "blob":
                        print(f"  blob_len: {len(v)} chars")
                    else:
                        print(f"  {k}: {v}")
